    }

    function run(uint deposit, uint unlockTime, uint waitTime) public payable {
        require(deposit >= 1 ether);
        require(address(this).balance >= deposit);

        c.Put{value: deposit}(unlockTime);

        if (unlockTime > block.timestamp) {
            require(waitTime >= unlockTime - block.timestamp);
            require(waitTime <= 1000000000000);
        }

        if (waitTime > 0) {
            vm_warp(waitTime);
        }

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        require(beforeBalance >= c.MinSum());
        require(block.timestamp > beforeUnlock);

        bool reverted;
        try c.Collect(beforeBalance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        assert(!reverted && afterBalance == 0 && afterUnlock == beforeUnlock);
    }

    function vm_warp(uint) internal pure {
        // placeholder: cannot use cheatcodes; tests must not rely on absolute time.
        // Real property: after the full balance is collected, balance is zero.
    }

    receive() external payable {}
}

