contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint unlockTime, uint value, uint collectAmount) public payable {
        require(value > 0);
        require(address(this).balance >= value);

        uint cBalanceBefore = address(c).balance;

        c.Put{value: value}(unlockTime);

        (uint storedUnlockTime, uint storedBalance) = c.Acc(address(this));

        assert(storedBalance == value);
        assert(storedUnlockTime == (unlockTime > block.timestamp ? unlockTime : block.timestamp));
        assert(address(c).balance == cBalanceBefore + value);

        bool canCollect = storedBalance >= c.MinSum()
            && storedBalance >= collectAmount
            && block.timestamp > storedUnlockTime;

        bool collectSucceeded = true;
        try c.Collect{value: 0}(collectAmount) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        (uint finalUnlockTime, uint finalBalance) = c.Acc(address(this));
        assert(finalUnlockTime == storedUnlockTime);

        if (canCollect) {
            assert(collectSucceeded);
            assert(finalBalance == storedBalance - collectAmount);
            assert(address(c).balance == cBalanceBefore + value - collectAmount);
        } else {
            assert(finalBalance == storedBalance);
            assert(address(c).balance == cBalanceBefore + value);
        }
    }

    receive() external payable {}
}

